const coletadoEm = new Date().toISOString();

const collectionId = `LAB-COLLECTION-${Date.now()}`;

const evidenciaOriginal = {
  evidence_id: "LAB-EV-001",
  type: "network_connection",
  description: "Conexao suspeita identificada no laboratorio.",
  src_ip: "192.0.2.10",
  dst_ip: "198.51.100.20",
  dst_port: 443
};

const novaEvidencia = {
  evidence_id: "LAB-EV-002",
  type: "host_observation",
  description: "Novo hostname associado ao evento original.",
  hostname: "lab-workstation-02"
};

const eventos = [

  // CENARIO 01 - EVENTO NOVO

  {
    sample_case: "NEW_EVENT",
    source_event_id: "LAB-0001",
    occurred_at: "2026-10-01T12:00:00Z",
    event_type: "suspicious_connection",
    severity: "medium",
    entity: {
      hostname: "lab-workstation-01",
      src_ip: "192.0.2.10",
      dst_ip: "198.51.100.20"
    },
    evidence: [
      evidenciaOriginal
    ]
  },

  // CENARIO 02 - REPETICAO SEM NOVA EVIDENCIA

  {
    sample_case: "EXACT_REPEAT",
    source_event_id: "LAB-0001",
    occurred_at: "2026-10-01T12:00:00Z",
    event_type: "suspicious_connection",
    severity: "medium",
    entity: {
      hostname: "lab-workstation-01",
      src_ip: "192.0.2.10",
      dst_ip: "198.51.100.20"
    },
    evidence: [
      evidenciaOriginal
    ]
  },

  // CENARIO 03 - EVENTO ORIGINAL ATUALIZADO

  {
    sample_case: "MATERIAL_UPDATE",
    source_event_id: "LAB-0001",
    occurred_at: "2026-10-01T12:00:00Z",
    event_type: "suspicious_connection",
    severity: "high",
    entity: {
      hostname: "lab-workstation-01",
      src_ip: "192.0.2.10",
      dst_ip: "198.51.100.20",
      related_hostnames: [
        "lab-workstation-02"
      ]
    },
    evidence: [
      evidenciaOriginal,
      novaEvidencia
    ]
  }

];

return eventos.map((evento, indice) => ({
  json: {

    schema_version: "1.0",

    environment: "LAB",

    collection_id: collectionId,

    collection_sequence: indice + 1,

    source: "SOC-LAB",

    collected_at: coletadoEm,

    ingested_at: coletadoEm,

    raw_event: evento

  }
}));

const items = $input.all();

function timestampValido(value) {
  return (
    typeof value === "string" &&
    !Number.isNaN(Date.parse(value)) &&
    /^\d{4}-\d{2}-\d{2}T/.test(value)
  );
}

return items.map((item, indice) => {

  const registro = item.json;

  const evento = registro.raw_event;

  const erros = [];

  if (registro.schema_version !== "1.0") {
    erros.push("Versao do contrato invalida.");
  }

  if (registro.environment !== "LAB") {
    erros.push("Somente eventos LAB sao permitidos.");
  }

  if (registro.source !== "SOC-LAB") {
    erros.push("Fonte nao autorizada para este teste.");
  }

  if (!registro.collection_id) {
    erros.push("collection_id obrigatorio.");
  }

  if (!timestampValido(registro.collected_at)) {
    erros.push("collected_at invalido.");
  }

  if (!timestampValido(registro.ingested_at)) {
    erros.push("ingested_at invalido.");
  }

  if (!evento || typeof evento !== "object") {
    erros.push("raw_event ausente.");
  } else {

    if (!evento.source_event_id) {
      erros.push("source_event_id obrigatorio.");
    }

    if (!timestampValido(evento.occurred_at)) {
      erros.push("occurred_at invalido.");
    }

    if (!evento.event_type) {
      erros.push("event_type obrigatorio.");
    }

    if (
      !["low", "medium", "high", "critical"]
        .includes(evento.severity)
    ) {
      erros.push("severity invalida.");
    }

    if (!evento.entity?.hostname) {
      erros.push("hostname obrigatorio.");
    }

    if (
      !Array.isArray(evento.evidence) ||
      evento.evidence.length === 0
    ) {
      erros.push("Lista de evidencias vazia.");
    } else {

      const ids = evento.evidence.map(
        evidence => evidence.evidence_id
      );

      if (ids.some(id => !id)) {
        erros.push("Evidencia sem identificador.");
      }

      if (new Set(ids).size !== ids.length) {
        erros.push("Evidencias duplicadas no mesmo registro.");
      }

    }

  }

  if (erros.length > 0) {
    throw new Error(
      `Evento ${indice + 1}: ${erros.join(" | ")}`
    );
  }

  return {
    json: {
      ...registro,
      validation: {
        status: "VALID",
        checked_at: new Date().toISOString(),
        errors: []
      }
    }
  };

});

const registros = $input.all();

return registros.map(item => {

  const registro = item.json;

  if (registro.validation?.status !== "VALID") {
    throw new Error(
      "Evento sem validacao. Entrega bloqueada."
    );
  }

  return {
    json: {

      ...registro,

      collector: "WF-01",

      target_workflow: "WF-02",

      collection_status: "COLLECTED_VALIDATED",

      dispatch_status: "MOCK_ONLY",

      real_execution_started: false,

      note:
        "Evento coletado e validado. " +
        "Deduplicacao reservada para o WF-02."

    }
  };

});

const entradas = $input.all();

if (entradas.length !== 3) {
  throw new Error(
    "LAB: esperados exatamente tres eventos WF-01."
  );
}

const registros = entradas
  .map(item => item.json)
  .sort(
    (a, b) =>
      a.collection_sequence - b.collection_sequence
  );

const casosEsperados = [
  "NEW_EVENT",
  "EXACT_REPEAT",
  "MATERIAL_UPDATE"
];

return registros.map((registro, indice) => {

  if (
    registro.schema_version !== "1.0" ||
    registro.environment !== "LAB" ||
    registro.source !== "SOC-LAB" ||
    registro.validation?.status !== "VALID" ||
    registro.collection_status !== "COLLECTED_VALIDATED" ||
    registro.dispatch_status !== "MOCK_ONLY" ||
    registro.real_execution_started !== false ||
    registro.target_workflow !== "WF-02"
  ) {
    throw new Error(
      "Contrato WF-01 nao autorizado para integracao."
    );
  }

  const evento = registro.raw_event;

  if (
    !evento ||
    typeof evento !== "object" ||
    Array.isArray(evento)
  ) {
    throw new Error("raw_event invalido.");
  }

  if (
    registro.collection_sequence !== indice + 1 ||
    evento.sample_case !== casosEsperados[indice] ||
    !evento.source_event_id ||
    !evento.occurred_at ||
    !evento.event_type ||
    !evento.severity ||
    !evento.entity ||
    !Array.isArray(evento.evidence) ||
    evento.evidence.length === 0
  ) {
    throw new Error(
      "Sequencia ou dados do evento LAB inconsistentes."
    );
  }

  return {
    json: {

      schema_version: registro.schema_version,
      environment: registro.environment,

      source: registro.source,

      source_event_id: evento.source_event_id,
      occurred_at: evento.occurred_at,
      event_type: evento.event_type,
      severity: evento.severity,

      entity: evento.entity,
      evidence: evento.evidence,

      sample_case: evento.sample_case,

      collection_id: registro.collection_id,
      collection_sequence: registro.collection_sequence,

      collected_at: registro.collected_at,
      ingested_at: registro.ingested_at,

      validation: registro.validation,

      collector: "WF-01",

      collection_status: registro.collection_status,

      integration_origin: "WF-01",
      integration_target: "WF-02",
      integration_mode: "LAB_MOCK",

      dispatch_status: "MOCK_ONLY",
      real_execution_started: false,

      raw_event: evento
    }
  };

});

const entradas = $input.all();

const historico = new Map();

function canonicalizar(valor) {
  if (Array.isArray(valor)) {
    return valor.map(canonicalizar);
  }

  if (valor && typeof valor === "object") {
    return Object.fromEntries(
      Object.keys(valor)
        .sort()
        .map(chave => [
          chave,
          canonicalizar(valor[chave])
        ])
    );
  }

  return valor;
}

function assinatura(valor) {
  return JSON.stringify(canonicalizar(valor));
}

function listaUnica(valores) {
  return [...new Set(valores)].sort();
}

const resultados = [];

for (const entrada of entradas) {

  const evento = entrada.json;

  if (
    evento.environment !== "LAB" ||
    evento.validation?.status !== "VALID"
  ) {
    throw new Error(
      "Evento invalido ou fora do ambiente LAB."
    );
  }

  const obrigatorios = [
    "source",
    "source_event_id",
    "occurred_at",
    "event_type",
    "severity"
  ];

  for (const campo of obrigatorios) {
    if (!evento[campo]) {
      throw new Error(
        `Campo obrigatorio ausente: ${campo}`
      );
    }
  }

  if (
    !Array.isArray(evento.evidence) ||
    evento.evidence.length === 0
  ) {
    throw new Error("Evento sem evidencias.");
  }

  const ids = evento.evidence.map(
    evidencia => evidencia.evidence_id
  );

  if (
    ids.some(id => !id) ||
    new Set(ids).size !== ids.length
  ) {
    throw new Error(
      "Identificadores de evidencias invalidos."
    );
  }

  const identityKey = assinatura([
    evento.source,
    evento.source_event_id,
    evento.event_type
  ]);

  const entidade = canonicalizar(evento.entity ?? {});

  const evidencias = [...evento.evidence]
    .map(canonicalizar)
    .sort((a, b) =>
      a.evidence_id.localeCompare(b.evidence_id)
    );

  const normalized = {
    source: evento.source,
    source_event_id: evento.source_event_id,
    occurred_at: evento.occurred_at,
    event_type: evento.event_type,
    severity: evento.severity,
    entity: entidade,
    evidence: evidencias
  };

  // Campos de transporte, horario da coleta e sample_case
  // nao fazem parte da assinatura de deduplicacao.

  const contentSignature = assinatura(normalized);

  const anterior = historico.get(identityKey);

  let status;
  let shouldAnalyze;
  let changedFields = [];
  let newEvidenceIds = [];

  if (!anterior) {

    status = "NEW_EVENT";
    shouldAnalyze = true;

    historico.set(identityKey, {
      occurrenceCount: 1,
      version: 1,
      latest: normalized,
      latestSignature: contentSignature,
      knownSignatures: new Set([contentSignature])
    });

  } else {

    anterior.occurrenceCount += 1;

    if (
      anterior.knownSignatures.has(contentSignature)
    ) {

      status = "EXACT_REPEAT";
      shouldAnalyze = false;

    } else {

      status = "MATERIAL_UPDATE";
      shouldAnalyze = true;

      const antigo = anterior.latest;

      if (antigo.severity !== normalized.severity) {
        changedFields.push("severity");
      }

      if (
        assinatura(antigo.entity) !==
        assinatura(normalized.entity)
      ) {
        changedFields.push("entity");
      }

      const antigosIds = new Set(
        antigo.evidence.map(e => e.evidence_id)
      );

      newEvidenceIds = normalized.evidence
        .map(e => e.evidence_id)
        .filter(id => !antigosIds.has(id));

      if (
        assinatura(antigo.evidence) !==
        assinatura(normalized.evidence)
      ) {
        changedFields.push("evidence");
      }

      if (
        antigo.occurred_at !== normalized.occurred_at
      ) {
        changedFields.push("occurred_at");
      }

      anterior.version += 1;
      anterior.latest = normalized;
      anterior.latestSignature = contentSignature;
      anterior.knownSignatures.add(contentSignature);

    }
  }

  const atual = historico.get(identityKey);

  resultados.push({
    json: {
      schema_version: "1.0",
      environment: "LAB",
      processor: "WF-02",

      collection_sequence:
        evento.collection_sequence,

      sample_case: evento.sample_case,

      identity_key: identityKey,

      content_signature: contentSignature,

      normalized_event: normalized,

      deduplication: {
        status,
        occurrence_count: atual.occurrenceCount,
        investigation_version: atual.version,
        changed_fields: listaUnica(changedFields),
        new_evidence_ids: listaUnica(newEvidenceIds)
      },

      decision: {
        should_analyze: shouldAnalyze,
        target_workflow: shouldAnalyze
          ? "WF-03"
          : null,
        reason:
          status === "NEW_EVENT"
            ? "Primeira ocorrencia."
            : status === "EXACT_REPEAT"
              ? "Conteudo previamente observado."
              : "Novas informacoes relevantes."
      },

      dispatch_status: "MOCK_ONLY",
      real_execution_started: false,
      processed_at: new Date().toISOString()
    }
  });

}

return resultados;

const registros = $input.all();

const permitidos = new Set([
  "NEW_EVENT",
  "EXACT_REPEAT",
  "MATERIAL_UPDATE"
]);

return registros.map(item => {

  const registro = item.json;

  const status = registro.deduplication?.status;

  if (!permitidos.has(status)) {
    throw new Error(
      "Classificacao de deduplicacao invalida."
    );
  }

  if (
    status === "EXACT_REPEAT" &&
    registro.decision.should_analyze !== false
  ) {
    throw new Error(
      "Repeticao nao pode solicitar nova analise."
    );
  }

  if (
    status !== "EXACT_REPEAT" &&
    registro.decision.should_analyze !== true
  ) {
    throw new Error(
      "Evento novo ou atualizado deveria ser elegivel."
    );
  }

  return {
    json: {
      ...registro,
      audit: {
        status: "VALIDATED",
        persistence: "NOT_ENABLED",
        notification_sent: false,
        ai_executed: false,
        checked_at: new Date().toISOString()
      }
    }
  };

});
